            Row spanning
          </label>
          ${['team', 'shift'].map((columnId) => {
            const column = table.getColumn(columnId)!
            return html`
              <label>
                <input
                  type="checkbox"
                  .checked=${column.getIsVisible()}
                  @change=${column.getToggleVisibilityHandler()}
                />
                ${String(column.columnDef.header)}
