    footer: (props) => props.column.id,
    size: 180,
  },
]

@customElement('lit-table-example')
class LitTableExample extends LitElement {
  private tableController = new TableController<typeof features, Person>(this)

  @state()
  private _data: Array<Person> = makeData(20)

  @state()
  private columnVisibility: ColumnVisibilityState = {}

  @state()
  private columnPinning: ColumnPinningState = { start: [], end: [] }

  @state()
  private columnSizing: ColumnSizingState = {}

  protected render() {
    const table = this.tableController.table(
      {
        features,
        columns: defaultColumns,
        data: this._data,
        state: {
          columnVisibility: this.columnVisibility,
          columnPinning: this.columnPinning,
          columnSizing: this.columnSizing,
        },
        onColumnVisibilityChange: (updaterOrValue) => {
          if (typeof updaterOrValue === 'function') {
            this.columnVisibility = updaterOrValue(this.columnVisibility)
          } else {
            this.columnVisibility = updaterOrValue
          }
        },
        onColumnPinningChange: (updaterOrValue) => {
          if (typeof updaterOrValue === 'function') {
            this.columnPinning = updaterOrValue(this.columnPinning)
          } else {
            this.columnPinning = updaterOrValue
          }
        },
        onColumnSizingChange: (updaterOrValue) => {
          if (typeof updaterOrValue === 'function') {
            this.columnSizing = updaterOrValue(this.columnSizing)
          } else {
            this.columnSizing = updaterOrValue
          }
        },
        columnResizeMode: 'onChange',
        // initialState: { columnPinning: { start: ['firstName'], end: [] } }, // `start`/`end` follow layout direction
        // atoms: { columnPinning: columnPinningAtom }, // preferred: own pinning state with an external atom
        // enableColumnPinning: false, // disable pinning for every column; default true
        debugTable: true,
        debugHeaders: true,
        debugColumns: true,
      },
      (state) => ({
        columnPinning: state.columnPinning,
        columnSizing: state.columnSizing,
      }),
    )

    const randomizeColumns = () => {
      table.setColumnOrder(
        faker.helpers.shuffle(table.getAllLeafColumns().map((d) => d.id)),
      )
    }

    return html`
      <div class="demo-root">
        <div class="column-toggle-panel">
          <div class="column-toggle-panel-header">
            <label>
              <input
                type="checkbox"
                .checked="${table.getIsAllColumnsVisible()}"
                @change="${table.getToggleAllColumnsVisibilityHandler()}"
              />
              Toggle All
            </label>
          </div>
          ${table.getAllLeafColumns().map(
            (column) => html`
              <div class="column-toggle-row">
                <label>
                  <input
                    type="checkbox"
                    .checked="${column.getIsVisible()}"
                    @change="${column.getToggleVisibilityHandler()}"
                  />
                  ${column.id}
                </label>
              </div>
            `,
          )}
        </div>
        <div class="spacer-md"></div>
        <div class="button-row">
          <button
            @click="${() => {
              this._data = makeData(20)
            }}"
            class="demo-button demo-button-sm"
          >
            Regenerate Data
          </button>
          <button
            @click="${() => {
              this._data = makeData(1_000)
            }}"
            class="demo-button demo-button-sm"
          >
            Stress Test (1k rows)
          </button>
          <button
            @click="${randomizeColumns}"
            class="demo-button demo-button-sm"
          >
            Shuffle Columns
          </button>
        </div>
        <div class="spacer-md"></div>
        <div class="table-container">
          <table
            style="${styleMap({ width: `${table.getCenterTotalSize()}px` })}"
          >
            <thead>
              ${repeat(
                table.getHeaderGroups(),
                (headerGroup) => headerGroup.id,
                (headerGroup) => html`
                  <tr>
                    ${repeat(
                      headerGroup.headers,
                      (header) => header.id,
                      (header) => {
                        const { column } = header
                        return html`
                          <th
                            colspan="${header.colSpan}"
                            style="${styleMap(getCommonPinningStyles(column))}"
                          >
                            <div class="nowrap">
                              ${
                                header.isPlaceholder
                                  ? null
                                  : html`${FlexRender({ header })} `
                              }
                              ${column.getIndex(
                                column.getIsPinned() || 'center',
                              )}
                            </div>
                            ${
                              !header.isPlaceholder && header.column.getCanPin()
                                ? html`
                                    <div class="pin-actions">
                                      ${
                                        header.column.getIsPinned() !== 'start'
                                          ? html`
                                              <button
                                                class="pin-button"
                                                @click="${() =>
                                                  header.column.pin('start')}"
                                              >
                                                ${'<='}
                                              </button>
                                            `
                                          : null
                                      }
                                      ${
                                        header.column.getIsPinned()
