import { customElement, state } from 'lit/decorators.js'
import { LitElement, html } from 'lit'
import { repeat } from 'lit/directives/repeat.js'
import {
  FlexRender,
  TableController,
  columnResizingFeature,
  columnSizingFeature,
  columnVisibilityFeature,
  createSortedRowModel,
  rowSortingFeature,
  sortFn_alphanumeric,
  sortFn_text,
  tableFeatures,
} from '@tanstack/lit-table'
import { styleMap } from 'lit/directives/style-map.js'
import { Ref, createRef, ref } from 'lit/directives/ref.js'
import { VirtualizerController } from '@tanstack/lit-virtual'
import { Person, makeColumns, makeData } from './makeData.ts'
import type { ColumnDef } from '@tanstack/lit-table'

const features = tableFeatures({
  columnResizingFeature,
  columnSizingFeature,
  columnVisibilityFeature,
  rowSortingFeature,
  sortedRowModel: createSortedRowModel(),
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    text: sortFn_text,
  },
})

const DEFAULT_ROW_COUNT = 1_000
const DEFAULT_COLUMN_COUNT = 1_000
const STRESS_ROW_COUNT = 10_000
const STRESS_COLUMN_COUNT = 10_000

const createColumns = (columnCount: number) =>
  makeColumns(columnCount) as Array<ColumnDef<typeof features, Person>>

@customElement('lit-table-example')
class LitTableExample extends LitElement {
  private tableController = new TableController<typeof features, Person>(this)

  private tableContainerRef: Ref = createRef()

  @state()
  private _columns = createColumns(DEFAULT_COLUMN_COUNT)

  @state()
  private _data = makeData(DEFAULT_ROW_COUNT, this._columns)

  private columnVirtualizerController?: VirtualizerController<Element, Element>
  private rowVirtualizerController?: VirtualizerController<Element, Element>

  private _sizingSub?: { unsubscribe: () => void }

  connectedCallback() {
    super.connectedCallback()
  }

  disconnectedCallback() {
    super.disconnectedCallback()
    this._sizingSub?.unsubscribe()
    this._sizingSub = undefined
  }

  private _ensureVirtualizers(
    visibleColumnCount: number,
    rowCount: number,
    visibleColumns: Array<any>,
  ) {
    // Create column virtualizer once we have the scroll element
    if (!this.columnVirtualizerController) {
      this.columnVirtualizerController = new VirtualizerController(this, {
        count: visibleColumnCount,
        estimateSize: (index: number) =>
          visibleColumns[index]?.getSize() ?? 150,
        getScrollElement: () => this.tableContainerRef.value!,
        horizontal: true,
        overscan: 3,
      })
    }

    if (!this.rowVirtualizerController) {
      this.rowVirtualizerController = new VirtualizerController(this, {
        count: rowCount,
        estimateSize: () => 33,
        getScrollElement: () => this.tableContainerRef.value!,
        overscan: 5,
      })
    }
  }

  private _refreshData() {
    const nextColumns = createColumns(DEFAULT_COLUMN_COUNT)
    this._columns = nextColumns
    this._data = makeData(DEFAULT_ROW_COUNT, nextColumns)
  }

  private _stressTestRows() {
    this._data = makeData(STRESS_ROW_COUNT, this._columns)
  }

  private _stressTestColumns() {
    const nextColumns = createColumns(STRESS_COLUMN_COUNT)
    this._columns = nextColumns
    this._data = makeData(this._data.length, nextColumns)
  }

  protected render() {
    const table = this.tableController.table(
      {
        features,
        columns: this._columns,
        data: this._data,
        columnResizeMode: 'onChange',
      },
      // header/cell widths render via header.getSize(), so the host must
      // re-render when column sizing changes
      (state) => ({ columnSizing: state.columnSizing }),
    )

    const visibleColumns = table.getVisibleLeafColumns()
    const { rows } = table.getRowModel()

    this._ensureVirtualizers(visibleColumns.length, rows.length, visibleColumns)

    const columnVirtualizer = this.columnVirtualizerController?.getVirtualizer()
    const rowVirtualizer = this.rowVirtualizerController?.getVirtualizer()

    if (!columnVirtualizer || !rowVirtualizer) {
      return html`<div>Loading...</div>`
    }

    // re-measure virtual column widths when a column is resized so the
    // virtualizer's scroll math stays in sync with the rendered widths
    if (!this._sizingSub) {
      this._sizingSub = table.atoms.columnSizing.subscribe(() => {
        this.columnVirtualizerController?.getVirtualizer().measure()
      })
    }

    // Update virtualizer counts
    columnVirtualizer.setOptions({
      ...columnVirtualizer.options,
      count: visibleColumns.length,
      estimateSize: (index: number) => visibleColumns[index]?.getSize() ?? 150,
    })
    rowVirtualizer.setOptions({
      ...rowVirtualizer.options,
      count: rows.length,
    })

    const virtualColumns = columnVirtualizer.getVirtualItems()
    const virtualRows = rowVirtualizer.getVirtualItems()

    let virtualPaddingLeft: number | undefined
    let virtualPaddingRight: number | undefined

    if (virtualColumns.length > 0) {
      virtualPaddingLeft = virtualColumns[0]?.start ?? 0
      virtualPaddingRight =
        columnVirtualizer.getTotalSize() -
        (virtualColumns[virtualColumns.length - 1]?.end ?? 0)
    }

    return html`
      <div class="app">
        <div>(${this._columns.length.toLocaleString()} columns)</div>
        <div>(${this._data.length.toLocaleString()} rows)</div>
        <button @click="${() => this._refreshData()}">Regenerate Data</button>
        <button @click="${() => this._stressTestRows()}">
          Stress Test (10k rows)
        </button>
        <button @click="${() => this._stressTestColumns()}">
          Stress Test (10k columns)
        </button>
        <div
          class="container"
          ${ref(this.tableContainerRef)}
          style="${styleMap({
            overflow: 'auto',
            position: 'relative',
            height: '800px',
          })}"
        >
          <table style="display: grid">
            <thead
              style="${styleMap({
                display: 'grid',
                position: 'sticky',
                top: '0',
                zIndex: '1',
              })}"
            >
              ${repeat(
                table.getHeaderGroups(),
                (headerGroup) => headerGroup.id,
                (headerGroup) => html`
                  <tr style="${styleMap({ display: 'flex', width: '100%' })}">
                    ${
                      virtualPaddingLeft
                        ? html`<th
                            style="${styleMap({
                              display: 'flex',
                              width: `${virtualPaddingLeft}px`,
                            })}"
                          ></th>`
                        : null
                    }
                    ${repeat(
                      virtualColumns,
                      (vc) => vc.index,
                      (virtualColumn) => {
                        const header = headerGroup.headers[virtualColumn.index]
                        return html`
                          <th
                            style="${styleMap({
                              display: 'flex',
                              position: 'relative',
                              width: `${header.getSize()}px`,
                            })}"
                          >
                            <div
                              class="${
                                header.column.getCanSort()
                                  ? 'sortable-header'
                                  : ''
                              }"
                              @click="${header.column.getToggleSortingHandler()}"
                            >
                              ${FlexRender({ header })}
                              ${
                                {
                                  asc: ' 🔼',
                                  desc: ' 🔽',
                                }[header.column.getIsSorted() as string] ?? null
                              }
                            </div>
                            <div
                              @dblclick="${() => header.column.resetSize()}"
                              @mousedown="${header.getResizeHandler()}"
                              @touchstart="${header.getResizeHandler()}"
                              class="resizer ${
                                header.column.getIsResizing()
                                  ? 'isResizing'
                                  : ''
                              }"
                            ></div>
                          </th>
                        `
                      },
                    )}
                    ${
                      virtualPaddingRight
                        ? html`<th
                            style="${styleMap({
                              display: 'flex',
                              width: `${virtualPaddingRight}px`,
                            })}"
                          ></th>`
                        : null
                    }
                  </tr>
                `,
              )}
            </thead>
            <tbody
              style="${styleMap({
                display: 'grid',
                height: `${rowVirtualizer.getTotalSize()}px`,
                position: 'relative',
              })}"
            >
              ${repeat(
                virtualRows,
                (item) => item.key,
                (virtualRow) => {
                  const row = rows[virtualRow.index]
                  const visibleCells = row.getVisibleCells()
                  return html`
                    <tr
                      data-index="${virtualRow.index}"
                      style="${styleMap({
                        display: 'flex',
                        position: 'absolute',
                        transform: `translateY(${virtualRow.start}px)`,
                        width: '100%',
                      })}"
                      ${ref((node) =>
                        rowVirtualizer.measureElement(node ?? null),
                      )}
                    >
                      ${
                        virtualPaddingLeft
                          ? html`<td
                              style="${styleMap({
                                display: 'flex',
                                width: `${virtualPaddingLeft}px`,
                              })}"
                            ></td>`
                          : null
                      }
                      ${repeat(
                        virtualColumns,
                        (vc) => vc.index,
                        (virtualColumn) => {
                          const cell = visibleCells[virtualColumn.index]
                          return html`
                            <td
                              style="${styleMap({
                                display: 'flex',
                                width: `${cell.column.getSize()}px`,
                              })}"
                            >
                              ${FlexRender({ cell })}
                            </td>
                          `
                        },
                      )}
                      ${
                        virtualPaddingRight
                          ? html`<td
                              style="${styleMap({
                                display: 'flex',
                                width: `${virtualPaddingRight}px`,
                              })}"
                            ></td>`
                          : null
                      }
                    </tr>
                  `
                },
              )}
            </tbody>
          </table>
        </div>
      </div>

      <style>
